parts.text:
[
  {
    "statement": "Two controlled, replicated trials in Spain and the United Kingdom measured the effect of adding municipal wastes or composts from municipal wastes to the soil.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "One trial found that adding municipal compost to semi-arid soils greatly reduced soil loss and water runoff.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "Another trial found mixed results from adding composts and wastes to soil.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "The soil types covered in the trials on municipal wastes were coarse loamy and sandy loam.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "Two other controlled, replicated trials from Spain and the United Kingdom measured the effect of adding organic processing wastes or composts from organic processing wastes to soil.",
    "citations": [
      "891"
    ]
  },
  {
    "statement": "One trial found that applying high rates of cotton gin compost and poultry manure improved soil structure.",
    "citations": [
      "891"
    ]
  },
  {
    "statement": "A trial found that applying high rates of cotton gin compost and poultry manure reduced soil loss.",
    "citations": [
      "891"
    ]
  },
  {
    "statement": "A trial found that applying high rates of cotton gin compost and poultry manure increased nutrient loss.",
    "citations": [
      "891"
    ]
  },
  {
    "statement": "Another trial found improved nutrient retention when molasses were added to soil.",
    "citations": [
      "891"
    ]
  },
  {
    "statement": "Another trial found increased barley Hordeum vulgare yield when molasses were added to soil.",
    "citations": [
      "891"
    ]
  },
  {
    "statement": "The soil types covered in trials on organic processing wastes were sandy-clay, sandy loam, and silty-clay.",
    "citations": [
      "891"
    ]
  }
]
